  <h3>Animaciones con @keyframes</h3>

  <CodeBlock
    language="css"
    filename="animaciones.css"
    code={`/* Definir animación */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Aplicar animación */
.element {
  animation: fadeIn 0.5s ease-out;
}

/* Animación con pasos */
@keyframes pulse {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.1);
  }
}

.icon {
  animation: pulse 2s infinite;
}`}
  />
